-- ── 0. Add email/phone columns if not already present ────────
ALTER TABLE public.app_users ADD COLUMN IF NOT EXISTS email text DEFAULT '';
ALTER TABLE public.app_users ADD COLUMN IF NOT EXISTS phone text DEFAULT '';

-- ── 1. DEPARTMENTS ───────────────────────────────────────────
-- departments has UNIQUE constraints on both id AND name.
-- We skip any row where EITHER already exists (preserves existing IDs).
INSERT INTO public.departments (id, name, description)
SELECT v.id, v.name, v.description
FROM (VALUES
  ('dept-civil',      'Civil Operations',      'Civil engineering and site works'),
  ('dept-mechanical', 'Mechanical Engineering', 'Mechanical systems and maintenance'),
  ('dept-electrical', 'Electrical',             'Electrical installations and inspections'),
  ('dept-hse',        'HSE',                    'Health, Safety and Environment'),
  ('dept-admin',      'Administration',         'HR, finance and admin support'),
  ('dept-logistics',  'Logistics',              'Fleet and supply chain management')
) AS v(id, name, description)
WHERE NOT EXISTS (
  SELECT 1 FROM public.departments d WHERE d.id = v.id OR d.name = v.name
);

-- ── 2. EMPLOYEES ─────────────────────────────────────────────
-- Password hash = bcrypt("Password1", cost 10)
-- department_id is resolved by JOINing on department NAME so it works
-- regardless of what ID the existing department row has.
-- Skips any row where id OR username already exists.
