  SELECT 1 FROM public.attendance a
  WHERE a.id = v.att_id
     OR (a.user_id = u.id AND a.work_date = v.work_date::date)
);

-- ── 5. LEAVE REQUESTS ────────────────────────────────────────
-- reviewed_by resolved dynamically via subquery on admin role
INSERT INTO public.leave_requests
  (id, user_id, username, department_id, type, from_date, to_date, days, reason, status, reviewed_by, reviewed_at, applied_at)
SELECT
  v.id,
  u.id AS user_id,
  v.uname,
  d.id AS department_id,
  v.type, v.from_date::date, v.to_date::date, v.days::int,
  v.reason, v.status,
  CASE WHEN v.status != 'pending'
    THEN (SELECT id FROM public.app_users WHERE role = 'admin' LIMIT 1)
    ELSE NULL END,
  CASE WHEN v.status != 'pending' THEN v.reviewed_at::timestamptz ELSE NULL END,
  v.applied_at::timestamptz
